/* From Uiverse.io by vinodjangid07 - Tags: gradient, button, connect, hover effect */
.__UIV_SCOPE__ .connectBtn {
  width: 120px;
  height: 40px;
  border: none;
  border-radius: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  color: white;
  font-weight: 600;
  background: linear-gradient( to right,#8be3fc,#576bff);
  box-shadow: 0 20px 30px -7px rgba(97, 118, 238, 0.5);
  transition: all 0.3s ease-in-out;
  cursor: pointer;
}

.__UIV_SCOPE__ .connectBtn:hover {
  box-shadow: none;
  transform: translate(0px, 2.2px);
}

.__UIV_SCOPE__ .connectBtn:active {
  transform: scale(0.96) translate(0px, 3.2px);
}
